 if($path==='/robots.txt'){header('Content-Type: text/plain; charset=utf-8');echo "User-agent: *\nAllow: /\nDisallow: ".$base."/api.php\nDisallow: ".$base."/app/\nDisallow: ".$base."/install.php\nSitemap: ".$origin."/sitemap.xml\n";exit;}
